<script setup lang="ts">
const props=defineProps<{consoleId:string}>(),emit=defineEmits<{saves:[titleId:string]}>()
const target=props.consoleId,request=useConsoleRequest(),{t,formatLocale}=useAppLocale()
const busy=ref(false),acting=ref(false),error=ref(''),entries=ref<any[]>([]),query=ref(''),platform=ref('all'),tab=ref('ready'),selected=ref(''),info=ref<any>(),capabilities=ref<any>({}),command=ref<any>(),confirmation=ref<any>(),typed=ref(''),destination=ref('/data/homebrew'),sort=ref('name'),notPlayed=ref(false)
const activity=ref<any>(),switching=ref(false)
let disposed=false,timer:ReturnType<typeof setTimeout>|undefined,activityTimer:ReturnType<typeof setTimeout>|undefined
const pending=computed(()=>switching.value||acting.value||command.value?.state==='unconfirmed'||command.value?.result?.job_id&&!['completed','failed','cancelled'].includes(command.value?.storage?.state))
const filtered=computed(()=>entries.value.filter(row=>(tab.value==='ready'?row.installed:(row.sourceType==='folder'||row.sourceType==='image')&&row.sourceAvailable)&&(platform.value==='all'||row.platform===platform.value)&&`${row.title} ${row.titleId} ${row.path||''}`.toLocaleLowerCase().includes(query.value.trim().toLocaleLowerCase())&&(!notPlayed.value||!row.lastAccessTime)).sort((a,b)=>sort.value==='recent'?(b.lastAccessTime||'').localeCompare(a.lastAccessTime||''):sort.value==='size'?(b.sizeBytes||0)-(a.sizeBytes||0):a.title.localeCompare(b.title,formatLocale.value)))
const groups=computed(()=>tab.value==='ready'?[{key:'ready',title:t('Игры и приложения'),rows:filtered.value}]:[{key:'folder',title:t('Папки игр'),rows:filtered.value.filter(r=>r.sourceType==='folder')},{key:'image',title:t('Образы дисков'),rows:filtered.value.filter(r=>r.sourceType==='image')}])
const runtimeReady=computed(()=>capabilities.value.consoleActivity===true&&activity.value?.complete===true)
const isRunning=(row:any)=>activity.value?.running===true&&activity.value.titleId===row.titleId
const labels:Record<string,string>={switch:'Закрыть текущую игру и запустить выбранную',launch:'Запустить',stop:'Остановить',mount:'Смонтировать',unmount:'Размонтировать',uninstall:'Удалить регистрацию',delete:'Удалить игру и файлы',copy:'Копировать',move:'Переместить',unpack:'Распаковать'}
function message(e:any){return e?.data?.message||e?.message||t('PS5 недоступна')}
async function load(){if(busy.value)return;busy.value=true;error.value='';try{const v=await request<any>('/api/ps5/management/games',{method:'POST',body:{consoleId:target}});if(disposed)return;entries.value=v.entries;capabilities.value=v.capabilities;await refreshActivity();selected.value='';info.value=undefined}catch(e){if(!disposed)error.value=message(e)}finally{busy.value=false}}
async function details(row:any){if(!capabilities.value.consoleGames){selected.value=row.titleId;info.value=row;return}error.value='';try{const v=await request<any>('/api/ps5/management/game-info',{method:'POST',body:{consoleId:target,titleId:row.titleId}});if(!disposed){selected.value=row.titleId;info.value={...row,...v};const old=entries.value.find(r=>r.titleId===row.titleId);if(old)Object.assign(old,v)}}catch(e){if(!disposed)error.value=message(e)}}
async function refreshActivity(){
  if(disposed)return undefined
  if(!capabilities.value.consoleActivity){activity.value=undefined;return undefined}
  try{const v=await request<any>('/api/ps5/management/game-activity',{method:'POST',body:{consoleId:target}});if(disposed)return undefined;activity.value=v;return v}catch(e){if(!disposed)activity.value=undefined;throw e}
}
async function watchActivity(){clearTimeout(activityTimer);if(disposed)return;try{if(!busy.value&&!acting.value&&!switching.value&&document.visibilityState==='visible')await refreshActivity()}catch(e){if(!disposed)error.value=message(e)}if(!disposed)activityTimer=setTimeout(watchActivity,5000)}
async function prepare(row:any,action:string){
  if(disposed||pending.value)return
  try{
    if(['launch','stop'].includes(action)){
      const active=await refreshActivity();if(disposed)return;if(!active?.complete)throw Error(t('Не удалось определить запущенную игру. Обновите состояние PS5.'))
      if(action==='launch'&&active.running){
        if(active.titleId===row.titleId)action='stop'
        else{await details(row);if(disposed||info.value?.titleId!==row.titleId||!info.value.sourceIdentity)return;confirmation.value={row:info.value,action:'switch',active:{...active,title:entries.value.find(r=>r.titleId===active.titleId)?.title||active.titleId}};return}
      }
      if(action==='stop'){
        if(!active.running||active.titleId!==row.titleId){error.value=t('Эта игра уже закрыта или запущено другое приложение.');return}
        await details(row);if(!disposed&&info.value?.titleId===row.titleId&&info.value.sourceIdentity)confirmation.value={row:info.value,action:'stop',appId:active.appId};return
      }
    }
    await details(row);if(disposed||!info.value?.sourceIdentity||info.value.titleId!==row.titleId)return
    if(['launch','mount','unmount'].includes(action)){await execute(info.value,action);return}
    confirmation.value={row:info.value,action};typed.value='';destination.value='/data/homebrew'
  }catch(e){if(!disposed)error.value=message(e)}
}
async function switchGame(){
  const choice=confirmation.value;if(disposed||choice?.action!=='switch'||pending.value)return;switching.value=true;error.value=''
  try{
    const active=await refreshActivity();if(disposed)return
    if(!active?.running||active.titleId!==choice.active.titleId||active.appId!==choice.active.appId)throw Error(t('Запущенная игра изменилась. Обновите список и подтвердите переключение снова.'))
    const row=await request<any>('/api/ps5/management/game-info',{method:'POST',body:{consoleId:target,titleId:active.titleId}})
    const stopped=await execute(row,'stop',active.appId,true)
    if(disposed||stopped?.state!=='accepted')return
    const deadline=Date.now()+10000
    for(;;){
      const now=await refreshActivity();if(disposed)return;if(now?.complete&&!now.running)break
      if(!now?.complete||now.appId!==active.appId||now.titleId!==active.titleId)throw Error(t('Запущенная игра изменилась. Новая игра не запускалась.'))
      if(Date.now()>=deadline)throw Error(t('PS5 ещё закрывает игру. Новая игра не запускалась; обновите состояние.'))
      await new Promise(resolve=>setTimeout(resolve,500))
    }
    await execute(choice.row,'launch',0,true)
  }catch(e){if(!disposed)error.value=message(e)}finally{switching.value=false;confirmation.value=undefined}
}
async function execute(row:any,action:string,expectedAppId=0,withinSwitch=false){if(disposed||pending.value&&!withinSwitch||!capabilities.value.consoleControl)return;acting.value=true;error.value='';const requestId=crypto.randomUUID().replaceAll('-','');try{const v=await request<any>('/api/ps5/management/game-command',{method:'POST',body:{consoleId:target,requestId,titleId:row.titleId,action,sourceIdentity:row.sourceIdentity,destination:destination.value,confirmTitleId:typed.value,expectedAppId},retry:0});if(!disposed){command.value=v;confirmation.value=undefined;await poll()}return v}catch(e){if(!disposed){error.value=message(e);confirmation.value=undefined;if(e?.data?.data?.commandNotDispatched===true){command.value=undefined;if(e?.data?.data?.activeGame){activity.value=e.data.data.activeGame}}else{command.value={id:requestId,titleId:row.titleId,action,state:'unconfirmed',message:error.value};await poll()}}}finally{acting.value=false}}
async function poll(){clearTimeout(timer);if(!command.value?.id||disposed)return;try{const v=await request<any>('/api/ps5/management/game-command-status',{method:'POST',body:{consoleId:target,requestId:command.value.id}});if(disposed)return;command.value=v;if(v.result?.job_id){command.value=await request<any>('/api/ps5/management/game-storage-status',{method:'POST',body:{consoleId:target,requestId:v.id}})}if(command.value.state==='accepted'&&(!command.value.result?.job_id||['completed','failed','cancelled'].includes(command.value.storage?.state)))await load()}catch(e:any){if(!disposed){if(e?.data?.data?.commandRecordMissing===true){command.value.recordMissing=true;error.value=command.value.message||message(e)}else error.value=message(e)}}if(!disposed&&(command.value?.state==='unconfirmed'&&!command.value.recordMissing||command.value?.result?.job_id&&!['completed','failed','cancelled'].includes(command.value.storage?.state)))timer=setTimeout(poll,2500)}
const size=(n:number|undefined)=>n===undefined?t('Размер ещё не рассчитан'):`${(n/1024**3).toLocaleString(formatLocale.value,{maximumFractionDigits:2})} ${t('ГБ')}`
function state(row:any){return isRunning(row)?t('Запущено'):row.mounted?t('Смонтировано'):row.installed?t('Зарегистрировано на PS5'):t('Файлы на консоли; не зарегистрировано')}
onMounted(async()=>{await load();if(!disposed)activityTimer=setTimeout(watchActivity,5000)});onBeforeUnmount(()=>{disposed=true;clearTimeout(timer);clearTimeout(activityTimer)})
</script>
<template><div class="pf-console-games">
<header><div><p class="eyebrow">PLAYSTATION 5</p><h1>{{t('На консоли')}}</h1><p>{{t('Игры, приложения и исходные файлы на выбранной приставке.')}}</p></div><button :disabled="busy||pending" @click="load">{{t(busy?'Загрузка…':'Обновить')}}</button></header>
<nav class="tabs" :aria-label="t('Раздел игр')"><button :class="{active:tab==='ready'}" @click="tab='ready'">◈ {{t('Готово к запуску')}}</button><button :class="{active:tab==='files'}" @click="tab='files'">▤ {{t('Файлы игр')}}</button></nav>
<p v-if="!capabilities.consoleControl&&!busy" class="notice">{{t('Список доступен. Запуск, удаление и управление файлами появятся после испытания обновлённого ELF на этой PS5.')}}</p>
<div class="controls"><input v-model="query" type="search" :placeholder="t('Название, Title ID или путь')"><select v-model="platform"><option value="all">{{t('Все платформы')}}</option><option value="ps4">PS4</option><option value="ps5">PS5</option></select><select v-model="sort"><option value="name">{{t('По названию')}}</option><option value="recent">{{t('Последний запуск')}}</option><option value="size">{{t('По размеру файлов')}}</option></select><label v-if="tab==='ready'"><input v-model="notPlayed" type="checkbox">{{t('Без отмеченного запуска')}}</label></div>
<p v-if="activity?.running" class="notice">{{t('Сейчас запущено')}}: {{entries.find(r=>r.titleId===activity.titleId)?.title||activity.titleId}}</p><p v-else-if="capabilities.consoleControl&&!runtimeReady&&!busy" class="notice">{{t('Запуск недоступен, пока служба не подтвердит состояние запущенной игры.')}}</p>
<p v-if="error" class="error" role="alert">{{error}}</p><p v-if="busy" role="status">{{t('Читаем игры выбранной PS5…')}}</p>
<section v-if="command" class="notice" aria-live="polite"><strong>{{command.titleId}} · {{t(labels[command.action]||command.action)}}</strong><p>{{t(command.state==='unconfirmed'?'Результат не подтверждён; команда повторно не отправляется':command.state==='failed'?'Команда не выполнена':command.storage?command.storage.state==='completed'?'Работа с файлами завершена':command.storage.state==='failed'?'Ошибка работы с файлами':'Обработка файлов на PS5':'Системная команда принята PS5')}}</p><p v-if="Number.isInteger(command.result?.code)&&command.result.code<0">PS5 API · {{`0x${(command.result.code>>>0).toString(16).toUpperCase().padStart(8,'0')}`}}</p><progress v-if="command.storage?.total_bytes" :value="command.storage.processed_bytes" :max="command.storage.total_bytes"/><button @click="poll">{{t('Проверить результат')}}</button></section>
<section v-for="group in groups" :key="group.key" class="game-section"><h2>{{group.title}} <small>{{group.rows.length}}</small></h2><p v-if="!group.rows.length&&!busy">{{t(tab==='files'&&!capabilities.consoleGames?'Для чтения исходных папок и образов нужна обновлённая служба PS5.':'Ничего не найдено.')}}</p><div class="game-grid"><ConsoleGameCard v-for="row in group.rows" :key="row.titleId" v-bind="{title:row.title,titleId:row.titleId,platform:row.platform,cover:row.cover,version:row.version,format:row.format,sizeBytes:row.sizeBytes,status:state(row),selected:selected===row.titleId}" @details="details(row)"><button class="primary" :disabled="pending||!capabilities.consoleControl||!runtimeReady||!row.installed" @click="prepare(row,isRunning(row)?'stop':'launch')">{{isRunning(row)?'■':'▷'}} {{t(isRunning(row)?'Стоп':'Запустить')}}</button><button v-if="tab==='files'" :disabled="pending||!capabilities.consoleControl||!row.canManageSource" @click="prepare(row,row.mounted?'unmount':'mount')">{{t(row.mounted?'Размонтировать':'Смонтировать')}}</button><button @click="details(row)">{{t('Сведения')}}</button><button class="danger" :disabled="pending||!capabilities.consoleControl||!row.canUninstall&&!row.canManageSource" @click="prepare(row,row.canManageSource?'delete':'uninstall')">{{t('Удалить')}}</button></ConsoleGameCard></div></section>
<section v-if="info" class="game-info"><header><h2>{{info.title}}</h2><button @click="info=undefined;selected=''">×</button></header><dl><dt>Title ID</dt><dd>{{info.titleId}}</dd><dt>{{t('Версия')}}</dt><dd>{{info.version||'—'}}</dd><dt>Content ID</dt><dd>{{info.contentId||'—'}}</dd><dt>{{t('Формат')}}</dt><dd>{{info.format||'—'}}</dd><dt>{{t('Исходные файлы')}}</dt><dd>{{info.path||t('Путь не предоставлен службой')}}</dd><dt>{{t('Размер исходных файлов')}}</dt><dd>{{size(info.sizeBytes)}}</dd><dt>{{t('Состояние')}}</dt><dd>{{state(info)}}</dd></dl><div class="info-actions"><button @click="emit('saves',info.titleId)">{{t('Сохранения')}}</button><button :disabled="pending||!capabilities.consoleControl||!runtimeReady||!isRunning(info)" @click="prepare(info,'stop')">{{t('Остановить')}}</button><template v-if="info.canManageSource"><button v-for="a in ['copy','move','unpack']" :key="a" :disabled="pending||!capabilities.consoleControl||a==='unpack'&&(info.sourceType!=='image'||!capabilities.consoleUnpack)" @click="prepare(info,a)">{{t(labels[a])}}</button><button :disabled="pending||!capabilities.consoleControl||!info.canUninstall" @click="prepare(info,'uninstall')">{{t('Удалить регистрацию')}}</button></template></div><p v-if="info.sourceType==='image'&&!capabilities.consoleUnpack">{{t('Распаковка образов на этой PS5 ещё не подтверждена. Монтирование использует исходный образ.')}}</p><p v-if="info.canManageSource">{{t('Удаление регистрации сохраняет исходные файлы: сканирование может вернуть игру в меню. «Удалить» удаляет и файлы игры. Сохранения остаются.')}}</p></section>
<div v-if="confirmation" class="backdrop" @click.self="!acting&&!switching&&(confirmation=undefined)"><section class="dialog" role="dialog" aria-modal="true" aria-labelledby="ps5-game-confirm"><h2 id="ps5-game-confirm">{{t(labels[confirmation.action])}}</h2><p>{{confirmation.row.title}} · {{confirmation.row.titleId}}</p><p>{{confirmation.row.path}}</p><template v-if="['delete','uninstall'].includes(confirmation.action)"><p>{{t(confirmation.action==='delete'?'Исходные файлы игры будут удалены безвозвратно. Сохранения останутся.':'Будет удалена системная регистрация. Исходные файлы и сохранения останутся.')}}</p><label>{{t('Введите Title ID для подтверждения')}}<input v-model="typed" autocomplete="off" spellcheck="false"></label></template><template v-else-if="['copy','move','unpack'].includes(confirmation.action)"><label>{{t('Каталог назначения')}}<select v-model="destination"><option value="/data/homebrew">{{t('Память консоли')}} · /data/homebrew</option><option v-for="n in 8" :key="n" :value="`/mnt/usb${n-1}`">USB {{n-1}}</option></select></label><p v-if="confirmation.action==='unpack'">{{t('Исходный образ сохраняется.')}}</p></template><template v-else-if="confirmation.action==='switch'"><p>{{t('Сейчас запущено')}}: {{confirmation.active.title}} · {{confirmation.active.titleId}}</p><p>{{t('Закрытие приложения может потерять несохранённый прогресс.')}}</p><p>{{t('Выбранная игра запустится только после подтверждённого закрытия текущей.')}}</p></template><p v-else>{{t('Закрытие приложения может потерять несохранённый прогресс.')}}</p><div class="info-actions"><button :disabled="acting||switching" @click="confirmation=undefined">{{t('Отмена')}}</button><button class="primary" :disabled="acting||pending||['delete','uninstall'].includes(confirmation.action)&&typed!==confirmation.row.titleId" @click="confirmation.action==='switch'?switchGame():execute(confirmation.row,confirmation.action,confirmation.appId||0)">{{t(acting?'Отправляем…':'Подтвердить')}}</button></div></section></div>
</div></template>
<style scoped>
.pf-console-games{max-width:1400px}header{display:flex;align-items:center;justify-content:space-between;gap:16px}h1{margin:0;font-size:30px}h2{font-size:17px;color:#eee6f5}h2 small{margin-left:8px;color:#aa97be;font-weight:400}.eyebrow{color:#ac8be1;font-size:10px;letter-spacing:1.5px}p{color:#b0a4be;font-size:13px;line-height:1.65}.tabs{display:flex;gap:20px;border-bottom:1px solid #403349;margin:24px 0}.tabs button{border:0;border-bottom:2px solid transparent;background:none;border-radius:0;padding:12px 2px;color:#aaa0b7}.tabs button.active{color:#c8a5f1;border-color:#ad82e4}.controls{display:flex;gap:10px;flex-wrap:wrap;margin:20px 0}.controls>input{flex:1;min-width:180px}.controls label{display:flex;align-items:center;gap:7px;font-size:12px;color:#bbaeC9}.game-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(180px,1fr));gap:16px}.game-section{margin:25px 0}.notice,.game-info{padding:18px;border:1px solid #594269;border-radius:12px;background:#261f30;margin:18px 0}.error{color:#f2a7be}.game-info{position:fixed;right:24px;top:90px;width:min(420px,calc(100vw - 40px));max-height:calc(100vh - 120px);overflow:auto;z-index:15;box-shadow:0 18px 65px #0009}.game-info dl{display:grid;grid-template-columns:125px 1fr;gap:12px;font-size:13px;color:#e2d4ed}.game-info dt{color:#a99ab9}.game-info dd{margin:0;overflow-wrap:anywhere}.info-actions{display:flex;gap:8px;flex-wrap:wrap}button,input,select{font:inherit;color:#eee4f7;background:#302637;border:1px solid #594269;border-radius:8px;padding:9px 12px}button{cursor:pointer}button:disabled{opacity:.5;cursor:default}input{background:#18131f}button.primary{background:#805db9;border-color:#a882d9}progress{width:100%;accent-color:#ac80e0}.backdrop{position:fixed;inset:0;background:#000b;z-index:30;display:grid;place-items:center;padding:20px}.dialog{max-width:560px;max-height:85vh;overflow:auto;padding:26px;background:#241c2c;border:1px solid #73548a;border-radius:16px}.dialog label{display:flex;flex-direction:column;gap:10px;margin:16px 0;color:#cbb7dd}.dialog p{overflow-wrap:anywhere}:is(button,input,select):focus-visible{outline:2px solid #ba94e9;outline-offset:2px}@media(max-width:600px){.game-grid{grid-template-columns:repeat(2,minmax(0,1fr));gap:10px}.game-info{position:fixed;right:24px;top:90px;width:min(420px,calc(100vw - 40px));max-height:calc(100vh - 120px);overflow:auto;z-index:15;box-shadow:0 18px 65px #0009}.game-info dl{grid-template-columns:1fr;gap:6px}.game-info dd{margin-bottom:10px}}
</style>
